function markPending(){hasPending=true;pendingRevision++;try{localStorage.setItem(PENDING_KEY,JSON.stringify({revision:pendingRevision,at:new Date().toISOString()}));}catch(e){}setCloudState(navigator.onLine===false?'offline':'pending');}
