function bar(k,v,max){return `<div class="chart-row"><span title="${esc(k)}">${esc(k)}</span><div class="bar-track"><div class="bar" style="width:${Math.max(0,Math.min(100,v/max*100))}%"></div></div><span class="num">${fmt(v,2)}</span></div>`;}
function referenceRows(){const s=stats(),ref=config().reference;if(!ref)return [];return (isN?['headcount','female','risk','health','pension','amount']:['headcount','amount']).map(k=>({key:k,actual:s[k],expected:ref[k],diff:ref[k]==null?null:C.round(s[k]-C.num(ref[k]),isN?0:2)}));}
function renderReference(){
 const rr=referenceRows(),value=(v,k)=>['headcount','female'].includes(k)?fmt(v,0):displayCash(v);
 $('reconciliation').innerHTML='<p class="hint">'+t('period')+': '+active+' · '+t('reference')+'</p>'+(rr.length?'<div class="table-wrap"><table><thead><tr><th></th><th>'+t('calculated')+'</th><th>'+t('expected')+'</th><th>'+t('diff')+'</th></tr></thead><tbody>'+rr.map(r=>'<tr><td>'+t(r.key==='amount'?'total':r.key)+'</td><td>'+value(r.actual,r.key)+'</td><td>'+(r.expected==null?'—':value(r.expected,r.key))+'</td><td><span class="tag '+(r.diff===0?'ok':'bad')+'">'+(r.diff==null?'—':value(r.diff,r.key))+'</span></td></tr>').join('')+'</tbody></table></div>':'<p class="hint">'+t('referenceMissing')+'</p>');
}

function renderTable(){const q=($('search').value||'').toLowerCase(),rs=scopeRows().filter(r=>[r.empId,r.name,r.nameKh,r.dept].join(' ').toLowerCase().includes(q));$('row-count').textContent=rs.length;$('table').innerHTML=rs.length?`<table><thead><tr><th>${t('period')}</th><th>${t('empId')}</th><th>${t('name')}</th><th>${t('dept')}</th>${isN?`<th>${t('salaryKHR')}</th><th>${t('risk')}</th><th>${t('health')}</th><th>${t('pension')}</th>`:`<th>${t('averageSalary')}</th><th>${t('months')}</th><th>${t('days')}</th><th>${t('contractType')}</th>`}<th class="num">${t('total')} USD / KHR</th><th></th></tr></thead><tbody>${rs.map(r=>`<tr><td>${r.period}</td><td>${esc(r.empId)}</td><td>${esc(r.name)}<br><small>${esc(r.nameKh)}</small></td><td>${esc(r.dept)}${r.section?'<br>'+esc(r.section):''}</td>${isN?[r.salaryKHR,r.risk,r.health,r.pension].map(v=>`<td class="num">${displayCash(v,r.period)}</td>`).join(''):`<td class="num">${fmt(r.averageSalary)}</td><td>${r.months}</td><td>${r.days}</td><td>${t(r.contractType)}</td>`}<td class="num">${displayCash(r.amount,r.period)}</td><td><button data-edit="${esc(r._syncId)}">${t('edit')}</button></td></tr>`).join('')}</tbody></table>`:`<div class="empty">${t('empty')}</div>`;document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=safe(()=>edit(ledger.find(r=>r._syncId===b.dataset.edit))));}
function shift(n){if(view==='day'||view==='week'){const d=new Date(anchor+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n*(view==='week'?7:1));anchor=d.toISOString().slice(0,10);}else {const d=new Date(active+'-01T00:00:00Z');d.setUTCMonth(d.getUTCMonth()+n*(view==='year'?12:view==='half'?6:1));active=d.toISOString().slice(0,7);anchor=config().paymentDate||active+'-01';}render();}
function modal(title,body,buttons=[]){const m=$('modal');m.innerHTML=`<div class="modal-header"><h2>${title}</h2><button id="modal-close" aria-label="${t('close')}">✕</button></div>${body}<div id="modal-error" class="notice hidden" role="alert"></div><div class="modal-footer">${buttons.map((b,i)=>`<button id="modal-action-${i}" class="${b.primary?'primary':''}">${b.label}</button>`).join('')}</div>`;$('modal-close').onclick=()=>m.close();buttons.forEach((b,i)=>$('modal-action-'+i).onclick=async()=>{const btn=$('modal-action-'+i);btn.disabled=true;try{await b.action();}catch(e){$('modal-error').textContent=e.message;$('modal-error').classList.remove('hidden');}finally{btn.disabled=false;}});if(!m.open)m.showModal();}
function newPeriod(){modal(t('newPeriod'),field('new-ym','period','month',active),[{label:t('confirm'),primary:true,action:()=>{const p=$('new-ym').value;if(!C.ym(p)||!isN&&!/-(06|12)$/.test(p))throw Error(t('invalid')+' · Jun / Dec');active=p;$('modal').close();render();}}]);}
function isLocked(p=active){return approval[p]&&['待審查','待核可','已核可','pending','verified','approved'].includes(approval[p].status);}
function assertEditable(p=active){if(isLocked(p))throw Error(t('locked'));}
function timestamp(){const max=Math.max(0,...ledger.map(r=>Date.parse(r.modifiedAt)||0));return new Date(Math.max(Date.now(),max+1)).toISOString();}
function upsert(r){const i=ledger.findIndex(x=>x._syncId===r._syncId);if(i>=0)ledger[i]=r;else ledger.push(r);}
function setConfig(p,v){upsert({_syncId:M+':'+p+':settings',_syncPeriod:p,period:p,kind:'settings',value:v,modifiedAt:timestamp()});}
function edit(record){const r=record?{...record}:{empId:'',name:'',nameKh:'',dept:'',gender:'F',dob:'',nssfId:'',salaryKHR:0,salaryUSD:0,status:'ACTIVE',pensionMode:'auto',joinDate:'',averageSalary:0,months:6,days:7.5,tax:0,sourceAmount:'',contractType:'unknown',period:active};assertEditable(r.period);const keys=isN?['empId','name','nameKh','dept','section','nssfId','dob','salaryKHR','salaryUSD']:['empId','name','nameKh','dept','section','joinDate','averageSalary','months','days','tax','sourceAmount'];const numbers=['salaryKHR','salaryUSD','averageSalary','months','days','tax','sourceAmount'];let body=`<p>${t('period')}: ${r.period}</p><div class="fields">${keys.map(k=>field('e-'+k,k,numbers.includes(k)?'number':/dob|joinDate/.test(k)?'date':'text',r[k]??'')).join('')}${isN?selectField('e-gender','gender',['F','M'],r.gender)+selectField('e-status','status',['ACTIVE','MATERNITY'],r.status)+selectField('e-pensionMode','pensionMode',['auto','yes','no'],r.pensionMode):selectField('e-contractType','contractType',['unknown','permanent','fixed'],r.contractType)}${field('e-reason','reason','text','')}</div>`;modal(t(record?'edit':'add'),body,[...(record?[{label:t('delete'),action:()=>{if(!confirm(t('delete')+' '+r.empId+' / '+r.period+'?'))return;return serial(async()=>{assertEditable(r.period);upsert({...record,deleted:true,modifiedAt:timestamp()});await persist();$('modal').close();render();scheduleSync();});}}]:[]),{label:t('save'),primary:true,action:()=>serial(async()=>{assertEditable(r.period);keys.forEach(k=>{const v=$('e-'+k).value;r[k]=numbers.includes(k)?(k==='sourceAmount'&&v===''?null:C.num(v)):v.trim();});if(!r.empId||!r.name)throw Error(t('invalid'));r.empId=r.empId.toUpperCase();r.reason=$('e-reason').value.trim();if(record&&!r.reason)throw Error(t('reason'));if(isN){['gender','status','pensionMode'].forEach(k=>r[k]=$('e-'+k).value);if(r.pensionMode!=='auto'&&!r.reason)throw Error(t('reason'));}else r.contractType=$('e-contractType').value;const id=M+':'+r.period+':'+r.empId;if(ledger.some(x=>!x.deleted&&x._syncId===id&&x._syncId!==record?._syncId))throw Error('Duplicate ID');if(record&&record._syncId!==id)upsert({...record,deleted:true,modifiedAt:timestamp()});upsert({...r,_syncId:id,_syncPeriod:r.period,kind:'employee',deleted:false,modifiedAt:timestamp()});await persist();$('modal').close();render();scheduleSync();})}]);}
async function importFile(file){if(pendingImport)throw Error('Finish the current import first');if(/\.json$/i.test(file.name)){const j=JSON.parse(await file.text());if(j.module!==M||!Array.isArray(j.records))throw Error('Wrong module / Invalid backup');pendingImport={backup:j,source:file.name,period:j.period||active,rows:j.records.filter(r=>r.kind==='employee'&&!r.deleted)};}else{if(!window.XLSX)throw Error('Excel library unavailable; reload with internet access');const wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true});pendingImport=C.parseWorkbook(wb,file.name,M,XLSX);pendingImport.period=pendingImport.period||(active.slice(0,4)+'-'+(pendingImport.monthHint||active.slice(5)));}const p=pendingImport;await new Promise(resolve=>{modal(t('import'),`<p>${esc(p.source)} · ${p.rows.length} ${t('rows')}</p><div class="notice">${t('filePeriod')}</div>${field('import-period','period','month',p.period)}<p>${t('headcount')}: ${p.rows.length}</p><p class="hint">${isN?'Salary KHR → round → min 400,000 / max 1,200,000 → 0.8% + 2.6% + 2% + 2%':'Average monthly wage ÷ 26 × 7.5 days; cash rounded to $0.1'}</p>`,[{label:t('cancel'),action:()=>{pendingImport=null;$('modal').close();resolve();}},{label:t('confirm'),primary:true,action:()=>serial(async()=>{const period=$('import-period').value;if(!C.ym(period)||!isN&&!/-(06|12)$/.test(period))throw Error(t('invalid'));assertEditable(period);let added=0,updated=0,skipped=0;if(p.backup){for(const r of p.backup.records){if(!C.ym(r.period)||r._syncId!==M+':'+r.period+':'+(r.kind==='settings'?'settings':String(r.empId).toUpperCase()))throw Error('Invalid backup key');assertEditable(r.period);}const before=JSON.stringify(ledger);ledger=C.merge(ledger,p.backup.records);if(before===JSON.stringify(ledger))skipped=p.rows.length;else updated=p.rows.length;}else{for(const row of p.rows){const id=M+':'+period+':'+row.empId,old=ledger.find(r=>r._syncId===id);const next={...old,...row,dept:row.dept||old?.dept||'',section:row.section||old?.section||'',period,_syncId:id,_syncPeriod:period,kind:'employee',source:p.source,deleted:false};if(old&&!old.deleted){const compare=x=>{const y={...x};delete y.modifiedAt;delete y.source;delete y.sourceRow;delete y.reason;delete y.departmentSource;delete y.reportUpdatedAt;return JSON.stringify(Object.keys(y).sort().map(k=>[k,y[k]]));};if(compare(old)===compare(next)){skipped++;continue;}updated++;}else added++;upsert({...next,modifiedAt:timestamp()});}if(!ledger.some(r=>r.kind==='settings'&&r.period===period)){const cfg=C.profile(M);if(!isN)cfg.reference={headcount:p.rows.length,amount:C.round(p.rows.reduce((s,r)=>s+C.num(r.sourceAmount),0),2),source:p.source};setConfig(period,cfg);}}active=period;await persist();pendingImport=null;$('modal').close();render();notify(t('importDone')+` · +${added} · Δ${updated} · =${skipped}`,'ok');if(added||updated)scheduleSync();resolve();})}]);$('modal').addEventListener('close',function onClose(){pendingImport=null;resolve();},{once:true});});}
function settings(){assertEditable();const p=config(),ref=p.reference||{},fields=isN?[['minimum','Minimum KHR'],['maximum','Maximum KHR'],['riskRate','Risk rate'],['healthRate','Health rate'],['pensionEmployerRate','Pension employer rate'],['pensionWorkerRate','Pension worker rate'],['pensionAge','Pension age limit']]:[['divisor','Wage divisor'],['months','Service months'],['payDays','Payment days'],['cashDecimals','Cash decimals']];modal(t('settings'),`<p>${active} · ${t('rulesNote')}</p><div class="fields">${field('cfg-date','paymentDate','date',p.paymentDate||'')}${fields.map(([k,label])=>`<label>${label}<input type="number" min="0" step="any" id="cfg-${k}" value="${p[k]}"></label>`).join('')}${!isN?`<label>${t('formula')} · Payroll<select id="cfg-wage"><option value="gross" ${p.wageBasis==='gross'?'selected':''}>Gross = Net + advance + NSSF + union + tax</option><option value="fixed" ${p.wageBasis==='fixed'?'selected':''}>Actual fixed pay (baseTotal)</option></select></label>`:''}</div>${isN?'<div class="notice">Factory 100% · Employee deduction = 0 KHR<br>Round salary KHR first. Round each 2% pension share separately.</div>':''}<h3>${t('reference')}</h3><div class="fields">${(isN?['headcount','female','risk','health','pension','amount']:['headcount','amount']).map(k=>field('ref-'+k,k==='amount'?'total':k,'number',ref[k]??'')).join('')}<label class="wide">PDF / Source<input id="ref-source" value="${esc(ref.source||'')}"></label><label>Reference #<input id="ref-number" value="${esc(ref.number||'')}"></label><label>Due date<input id="ref-due" type="date" value="${esc(ref.dueDate||'')}"></label>${field('cfg-reason','reason','text','')}</div>`,[{label:t('save'),primary:true,action:()=>serial(async()=>{const reason=$('cfg-reason').value.trim();if(!reason)throw Error(t('reason'));const next={...p,paymentDate:$('cfg-date').value,reason};fields.forEach(([k])=>{const v=Number($('cfg-'+k).value);if(!Number.isFinite(v)||v<0)throw Error(t('invalid'));next[k]=v;});if(isN){if(next.maximum<next.minimum||next.pensionAge<18||['riskRate','healthRate','pensionEmployerRate','pensionWorkerRate'].some(k=>next[k]>1))throw Error(t('invalid'));next.factoryFull=true;}else{if(!next.divisor||next.months!==6||next.payDays!==7.5||![0,1,2].includes(next.cashDecimals))throw Error(t('invalid')+' · 6 months / 7.5 days');next.wageBasis=$('cfg-wage').value;}const r={source:$('ref-source').value.trim(),number:$('ref-number').value.trim(),dueDate:$('ref-due').value},keys=isN?['headcount','female','risk','health','pension','amount']:['headcount','amount'];let filled=0;keys.forEach(k=>{const v=$('ref-'+k).value;if(v!==''){r[k]=C.num(v);filled++;}});if(filled&&filled!==keys.length)throw Error('Complete every reference value, or leave all blank');next.reference=filled?r:null;assertEditable();setConfig(active,next);await persist();$('modal').close();render();scheduleSync();})}]);}
async function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('AC_HRPAY_BENEFITS',1);req.onupgradeneeded=()=>req.result.createObjectStore('modules',{keyPath:'module'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function persist(options={}){
  if(!db)db=await openDB();const signature=JSON.stringify(ledger);
  const changed=signature!==persistedSignature;
  if(changed&&!options.fromCloud)markPending();
  const snapshot=JSON.parse(signature),pending=hasPending;
  await new Promise((resolve,reject)=>{const tx=db.transaction('modules','readwrite');tx.objectStore('modules').put({module:M,records:snapshot,pending,cloudConfirmed:!pending});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Save aborted'));});
  persistedSignature=signature;if(changed&&!options.fromCloud)scheduleSync(80);
}
async function restore(){
  db=await openDB();await new Promise((resolve,reject)=>{const req=db.transaction('modules').objectStore('modules').get(M);req.onsuccess=()=>{
    const saved=req.result||{};ledger=saved.records||[];persistedSignature=JSON.stringify(ledger);
    hasPending=!!saved.pending||!!localStorage.getItem(PENDING_KEY)||(ledger.length>0&&saved.cloudConfirmed!==true);
    if(hasPending)markPending();
    const ps=periods().filter(p=>rawRows(p).length);if(ps.length)active=ps.at(-1);anchor=config().paymentDate||active+'-01';resolve();};req.onerror=()=>reject(req.error);
  });
}
function scheduleSync(delay=80){
  clearTimeout(timer);if(!hasPending&&ledger.length)markPending();
  setCloudState(navigator.onLine===false?'offline':'pending');
  if(navigator.onLine===false)return;
  const run=()=>{if(!hasPending)return;if(syncBusy){timer=setTimeout(run,250);return;}return serial(()=>sync(true)).catch(e=>setCloudState('error',e.message));};timer=setTimeout(run,delay);
}

async function api(data){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),60000);try{const res=await fetch(GAS_URL,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(data),signal:controller.signal});const j=await res.json();if(!res.ok||j.ok!==true)throw Error(j.error||'GAS response failed');return j.data||j;}finally{clearTimeout(timeout);}}
async function sync(push){
  if(push)clearTimeout(timer);
  if(navigator.onLine===false){setCloudState('offline');throw Error(t('online'));}
  syncBusy=true;setCloudState('syncing');['upload','download'].forEach(k=>$('btn-'+k).disabled=true);
  const revision=pendingRevision;
  try{
    const apply=async rows=>{ledger=C.merge(ledger,rows);await persist({fromCloud:true});if(!rawRows(active).length){const ps=periods().filter(p=>rawRows(p).length);if(ps.length)active=ps.at(-1);}render();};
    const snapshot=JSON.parse(JSON.stringify(ledger));
    const options={url:GAS_URL,tool,localRecords:snapshot,records:snapshot,mergeRecords:C.merge,meta:{module:M,periods:periods().filter(p=>rawRows(p).length)},apply,onStatus:s=>{notify(s);setCloudState('syncing',s);},context:{reason:'benefits'}};
    const result=push?await HRPaySmartSync.push(options):await HRPaySmartSync.pull(options);
    if(!result||result.ok!==true&&!result.noCloud)throw Error('Cloud did not confirm completion');
    if(push&&result.records)await apply(result.records);
    if(push&&result.ok===true&&pendingRevision===revision){hasPending=false;localStorage.removeItem(PENDING_KEY);await persist({fromCloud:true});retryCount=0;}
    if(hasPending)setCloudState('pending');else setCloudState(result.noCloud?'empty':'synced',new Date().toLocaleTimeString());
    notify(result.noCloud?t('online'):t('saved')+' · ↑ '+(result.uploaded||0)+' / ↓ '+(result.downloaded||0)+' · '+periods().filter(p=>rawRows(p).length).join(', '),'ok');
    return result;
  }catch(e){retrySync();setCloudState('error',e.message);throw e;}
  finally{syncBusy=false;['upload','download'].forEach(k=>$('btn-'+k).disabled=false);if(!push&&hasPending)scheduleSync(80);}
}

async function refreshApproval(show=true){try{const res=await fetch(GAS_URL+'?action=approvalStatus&module='+M);const j=await res.json();if(!res.ok||j.ok!==true)throw Error(j.error||'Approval status unavailable');const d=j.data||j;approval={};(d.records||[]).forEach(r=>approval[r.period]=r);render();if(show)notify(t('saved'),'ok');}catch(e){if(show)throw e;}}
